1091	}
1092	
1093	// The cancelled terminal shape: the run stops where it is, keeps the
1094	// context, trace and attempt records produced so far, and never carries a
1095	// success result. Compensation for already-succeeded actions is attached by
1096	// withCompensation under the usual rules.
1097	function cancelledResult(state) {
1098	  return {
1099	    status: 'cancelled',
1100	    context: state.context,
1101	    trace: state.trace,
1102	    actionAttempts: state.actionAttempts,
1103	  };
1104	}
